    "analysis": "（1）由基本不等式 $tx+\\dfrac{4}{t}y\\ge 2\\sqrt{tx\\cdot\\dfrac{4}{t}y}=2\\sqrt{4xy}=2\\sqrt{16}=8$，等号成立 $\\Leftrightarrow tx=\\dfrac{4}{t}y\\Leftrightarrow t^{2}x=4y$。再代入 $xy=4$ 得 $y=\\dfrac{4}{x}$，故 $t^{2}x=\\dfrac{16}{x}\\Rightarrow t^{2}x^{2}=16$。因 $t,x>0$，有 $tx=4$，即 $x=\\dfrac{4}{t}$，$y=t$。反之，该对满足 $xy=4$ 且使等号成立。\n（2）等号点满足 $\\dfrac{4}{t}+t=4$。两边乘 $t$：$4+t^{2}=4t\\Rightarrow(t-2)^{2}=0$，故 $t=2$ 唯一，此时 $(x,y)=(2,2)$。\n（3）同理 $\\dfrac{4}{t}+t=5\\Rightarrow t^{2}-5t+4=0\\Rightarrow(t-1)(t-4)=0$。$t=1$ 时 $(x,y)=(4,1)$；$t=4$ 时 $(x,y)=(1,4)$。与（2）对照：同一乘积约束下，线性约束的常数项改变会使等号解个数从 1 分岔为 2。",
