    "hardLevel": "H2",
    "hardLevelReason": "须先完整分类 m(a)=min(x²+|x-a|)，再解 m(a)≥a；误把端点 a² 当全局最小会得到假范围 a≥1。",
    "methodMain": "classification",
    "methodAux": "num_shape",
    "sourceType": "original",
    "sourceEvidence": "HARD14 原创；QUALITY-FIX-1D 重建；非高考真题",
    "stem": "设 $g_a(x)=x^{2}+|x-a|$，$m(a)=\\min_{x\\in\\mathbb{R}} g_a(x)$。\n（1）按实数 $a$ 分类写出 $m(a)$；\n（2）求使 $g_a(x)\\ge a$ 对一切实数 $x$ 恒成立的 $a$ 的集合，并说明边界可否取等。",
    "options": null,
    "answer": "（1）当 $a\\le\\dfrac12$ 时 $m(a)=a^{2}$；当 $a\\ge\\dfrac12$ 时 $m(a)=a-\\dfrac14$。\n（2）$a\\le 0$；在 $a=0$ 处 $x=0$ 取等。",
    "analysis": "右支 $x\\ge a$：$g=x^{2}+x-a=\\left(x+\\tfrac12\\right)^{2}-a-\\tfrac14$，在 $[a,+\\infty)$ 上随 $x$ 增大而增大（二次开口向上且对称轴 $x=-\\tfrac12\\le a$ 时更在左侧）。左支 $x\\le a$：$g=x^{2}-x+a=\\left(x-\\tfrac12\\right)^{2}+a-\\tfrac14$，对称轴 $x=\\tfrac12$。\n当 $a\\ge\\tfrac12$ 时对称轴落在左支，左支最小候选为 $a-\\tfrac14$；右支端点值 $a^{2}$。因 $a-\\tfrac14<a^{2}$（$a\\ne\\tfrac12$ 时严格），故 $m(a)=a-\\tfrac14$。\n当 $a\\le\\tfrac12$ 时，左支在 $(-\\infty,a]$ 上对称轴在右侧，故在该区间递减，最小值在 $x=a$ 为 $a^{2}$；右支最小值亦在 $x=a$。若 $a<-\\tfrac12$，右支在 $x=-\\tfrac12$ 取值 $a+\\tfrac14$，但由 $\\left(a-\\tfrac12\\right)^{2}\\ge 0$ 得 $a^{2}\\le a+\\tfrac14$，故全局最小仍为 $a^{2}$。总结：$a\\le\\tfrac12$ 时 $m(a)=a^{2}$；$a\\ge\\tfrac12$ 时 $m(a)=a-\\tfrac14$。\n（2）$m(a)\\ge a$：若 $a\\le 0$，右边非正而 $g\\ge 0$，成立，$a=0$ 时 $x=0$ 取等。若 $0<a\\le\\tfrac12$，则 $a^{2}<a$。若 $a\\ge\\tfrac12$，则 $a-\\tfrac14<a$（反例 $a=1$ 时 $m=\\tfrac34<1$）。故仅 $a\\le 0$。",
    "maxScore": 14,
