    "analysis": "（1）对 $x<0$，有 $-x>0$，故 $f(x)=f(-x)=(-x)^{2}-3(-x)+1=x^{2}+3x+1$。\n（2）按 $x$ 与 $2x+1$ 的符号分段。\n① $x\\ge 0$（此时 $2x+1>0$）：两边均用非负支，$x^{2}-3x+1=(2x+1)^{2}-3(2x+1)+1=4x^{2}-2x-1$，整理得 $3x^{2}+x-2=0$，$(3x-2)(x+1)=0$，得 $x=\\dfrac{2}{3}$ 或 $x=-1$（舍去）。\n② $x<-\\dfrac{1}{2}$（此时 $2x+1<0$）：两边均用负支，$x^{2}+3x+1=(2x+1)^{2}+3(2x+1)+1=4x^{2}+10x+5$，整理得 $3x^{2}+7x+4=0$，$(3x+4)(x+1)=0$，得 $x=-\\dfrac{4}{3}$ 或 $x=-1$，均属于本段。\n③ $-\\dfrac{1}{2}\\le x<0$（此时 $2x+1\\ge 0$）：左负右非负，$x^{2}+3x+1=4x^{2}-2x-1$，整理得 $3x^{2}-5x-2=0$，$(3x+1)(x-2)=0$，得 $x=-\\dfrac{1}{3}$（属于本段）或 $x=2$（舍去）。\n综上解集为 $\\left\\{-\\dfrac{4}{3},-1,-\\dfrac{1}{3},\\dfrac{2}{3}\\right\\}$。",
