    "sourceType": "original",
    "sourceEvidence": "HARD14 设计档案落地原创；非高考真题；离线候选",
    "stem": "设 $f$ 在 $\\mathbb{R}$ 上严格递增。对实参数 $a$，记不等式 $f(|x|-1)\\le f(a-x)$ 的解集为 $S(a)$。\n（1）将不等式等价转化为不含 $f$ 的不等式；\n（2）按 $a$ 分类求出 $S(a)$，并指出何时 $S(a)=\\varnothing$、何时 $S(a)$ 为无界集。",
    "options": null,
    "answer": "（1）$|x|+x\\le a+1$；（2）$a<-1$ 时 $S(a)=\\varnothing$；$a\\ge -1$ 时 $S(a)=\\left(-\\infty,\\dfrac{a+1}{2}\\right]$（无界）",
    "analysis": "（1）$f$ 严格递增，故 $f(|x|-1)\\le f(a-x)\\Leftrightarrow |x|-1\\le a-x\\Leftrightarrow |x|+x\\le a+1$。\n（2）分段讨论。\n当 $x\\ge 0$ 时，$2x\\le a+1\\Leftrightarrow x\\le\\dfrac{a+1}{2}$，再与 $x\\ge 0$ 求交。\n当 $x<0$ 时，$|x|+x=0$，不等式化为 $0\\le a+1\\Leftrightarrow a\\ge -1$：若 $a\\ge -1$ 则一切 $x<0$ 均成立；若 $a<-1$ 则负半轴无解。\n汇总：若 $a<-1$，非负支因 $\\dfrac{a+1}{2}<0$ 与 $[0,+\\infty)$ 无交，负半轴亦无解，故 $S(a)=\\varnothing$。若 $a\\ge -1$，负半轴全部属于解集，非负支贡献 $\\left[0,\\dfrac{a+1}{2}\\right]$，故 $S(a)=\\left(-\\infty,\\dfrac{a+1}{2}\\right]$，为无界集。",
