    "options": null,
    "answer": "当 $t\\le 0$ 时恰有一正根；当 $t>0$ 时：若 $1>m(t)$ 两根，若 $1=m(t)$ 一根（切），若 $1<m(t)$ 无根，其中 $m(t)$ 为 $h_t$ 在其唯一临界点处的最小值（临界点 $x=\\left(\\dfrac{\\beta t}{\\alpha}\\right)^{\\!1/(\\alpha-\\beta)}$，当 $\\beta>0$；若 $\\beta=0$ 则 $h_t(x)=x^{\\alpha}-t$，严格增，恰一正根对一切 $t$）。",
    "analysis": "先设 $\\beta>0$。令 $u=x^{\\alpha-\\beta}>0$，则 $h_t(x)=x^{\\beta}(u-t)$。\n若 $t\\le 0$，则 $u-t>0$，且 $x\\mapsto x^{\\beta}$ 与 $u$ 均随 $x$ 增大而增大，故 $h_t$ 在 $(0,+\\infty)$ 严格递增；$h_t(0^{+})=0$，$h_t\\to+\\infty$，因此与 $y=1$ 恰有一交点。\n若 $t>0$，可验证 $h_t$ 先减后增：在 $x_0=\\left(\\dfrac{\\beta t}{\\alpha}\\right)^{1/(\\alpha-\\beta)}$ 处取最小值 $m=h_t(x_0)$（由比较相邻点或配方型估值得到唯一谷点）。于是：若 $1>m$ 两正根；若 $1=m$ 一正根（谷点相切）；若 $1<m$ 无正根。\n若 $\\beta=0$，则 $h_t(x)=x^{\\alpha}-t$ 严格增，对任意实数 $t$ 恰有一正根。",
